export function gitAuthArgs(remoteUrl: string, token: string): string[] {
  if (remoteUrl.includes("github.com")) {
    return ["-c", `http.extraHeader=Authorization: Bearer ${token}`];
  }
  return [];
}

export async function cloneRepo(repo: Repo): Promise<string> {
  const dest = cachePath(repo.id);
  await exec("git", [...gitAuthArgs(repo.remoteUrl, SERVICE_TOKEN), "clone", repo.remoteUrl, dest]);
  return dest;

async registerRepo(req: Request) {
  const { id, remoteUrl } = req.body;
  if (!id || !remoteUrl) return { status: 400 };
  await store.insertRepo({ id, remoteUrl, owner: req.user.oid });
  await cloneRepo({ id, remoteUrl, owner: req.user.oid });
  return { status: 201 };
},
